<?php
namespace App\Http\Controllers\Admin; use App\Domain\Installation\WebsiteSettings; use App\Domain\Testimonials\{TestimonialDependencyInspector,TestimonialManager,TestimonialViewData}; use App\Http\Controllers\{Controller,PublicSiteController}; use App\Http\Requests\Testimonials\SaveTestimonialRequest; use App\Models\{Client,Testimonial}; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Validation\Rule; class TestimonialController extends Controller { public function index(Request $r):View{$f=$r->validate(['search'=>['nullable','string','max:160'],'client'=>['nullable','integer'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'rating'=>['nullable','integer','between:1,5'],'archived'=>['nullable','in:with,only,without']]);$q=Testimonial::with('client')->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('person_name','like',"%$v%")->orWhere('quote','like',"%$v%")))->when($f['client']??null,fn($q,$v)=>$q->where('client_id',$v))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when($f['rating']??null,fn($q,$v)=>$q->where('rating',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only')$q->whereNotNull('archived_at');elseif(($f['archived']??'without')==='without')$q->whereNull('archived_at');return view('admin.testimonials.index',['testimonials'=>$q->orderBy('display_order')->paginate(20)->withQueryString()]);} public function create():View{return $this->editor(new Testimonial);} public function store(SaveTestimonialRequest $r,TestimonialManager $m):RedirectResponse{return redirect()->route('admin.testimonials.edit',$m->save($r->validated(),null,$r->user()->id));} public function edit(Testimonial $testimonial):View{return $this->editor($testimonial);} public function update(SaveTestimonialRequest $r,Testimonial $testimonial,TestimonialManager $m):RedirectResponse{$m->save($r->validated(),$testimonial,$r->user()->id);return back();} private function editor(Testimonial $item):View{return view('admin.testimonials.editor',['testimonial'=>$item,'clients'=>Client::whereNull('archived_at')->orderBy('name')->limit(200)->get(),'dependencies'=>$item->exists?app(TestimonialDependencyInspector::class)->inspect($item):null]);} public function publish(Testimonial $testimonial,TestimonialManager $m):RedirectResponse{$m->publish($testimonial);return back();} public function schedule(Request $r,Testimonial $testimonial,TestimonialManager $m):RedirectResponse{$v=$r->validate(['scheduled_for'=>['required','date']]);$tz=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$m->schedule($testimonial,Carbon::parse($v['scheduled_for'],$tz)->utc()->toDateTimeString());return back();} public function unpublish(Testimonial $testimonial,TestimonialManager $m):RedirectResponse{$m->unpublish($testimonial);return back();} public function archive(Testimonial $testimonial,TestimonialManager $m):RedirectResponse{$m->archive($testimonial);return back();} public function restore(Testimonial $testimonial,TestimonialManager $m):RedirectResponse{$m->restore($testimonial);return back();} public function duplicate(Request $r,Testimonial $testimonial,TestimonialManager $m):RedirectResponse{return redirect()->route('admin.testimonials.edit',$m->duplicate($testimonial,$r->user()->id));} public function move(Testimonial $testimonial,string $direction,TestimonialManager $m):RedirectResponse{$m->move($testimonial,$direction);return back();} public function preview(Request $r,Testimonial $testimonial,TestimonialViewData $d):Response{return response()->view('testimonials.preview',['testimonial'=>$d->preview($testimonial)]+app(PublicSiteController::class)->sharedViewData($r))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} }
